const fs = require('node:fs')
const path = require('node:path')

const root = path.resolve(__dirname, '..')
const groups = ['img', 'gif']
const lines = [
  '// Generated by scripts/generate-media-manifest.js. Do not edit by hand.',
  'export const EXERCISE_MEDIA = {',
]

for (const group of groups) {
  const directory = path.join(root, 'assets', 'exercises', group)
  for (const name of fs.readdirSync(directory).sort()) {
    if (!/\.(png|jpe?g|webp|gif)$/i.test(name)) continue
    lines.push(`  ${JSON.stringify(`${group}/${name}`)}: require(${JSON.stringify(`../../assets/exercises/${group}/${name}`)}),`)
  }
}

lines.push('}', '')
fs.mkdirSync(path.join(root, 'src', 'services'), { recursive: true })
fs.writeFileSync(path.join(root, 'src', 'services', 'exercise-media-manifest.js'), lines.join('\n'))
